// Exploration: build the canvas fixture and report DOM facts.
import { openCanvas, dropNode, shapes, centerOf, readState, writeState, NT, fm, sleep } from "./canvaslib.mjs";
import { mouse, move } from "./lib.mjs";

export default {
  name: "explore canvas fixture",
  input: "create canvas, drop Evidence + Claim, draw 'supports' with the relation tool",
  expected: "2 nodes + 1 relation",
  run: async (ctx) => {
    const { client, json } = ctx;
    const ev = await ctx.writeNote("ev-node.md", fm(NT.evidence, "evidence body"));
    const cl = await ctx.writeNote("cl-node.md", fm(NT.claim, "claim body"));
    await sleep(800);
    const st = await openCanvas(ctx, { fresh: true });
    st.ev = ev; st.cl = cl; writeState(st);
    const vp = await client.evaluate(`const ed = window.__dgEditor; const b = ed.getViewportPageBounds(); return { x: b.x, y: b.y, w: b.w, h: b.h };`);
    await dropNode(ctx, ev, { x: vp.x + vp.w * 0.25, y: vp.y + vp.h * 0.5 });
    await dropNode(ctx, cl, { x: vp.x + vp.w * 0.6, y: vp.y + vp.h * 0.5 });
    await client.waitFor(`return window.__dgEditor.getCurrentPageShapes().filter((s) => s.type === "discourse-node").length >= 2`, { label: "2 nodes" });
    await sleep(800);
    const nodes = (await shapes(ctx)).filter((s) => s.type === "discourse-node");
    // Relation tool: show panel, click 'supports', drag Evidence -> Claim.
    await client.evaluate(`window.__dgEditor.setCurrentTool("discourse-node"); return true;`);
    await sleep(500);
    const panel = await client.evaluate(`
      const root = app.workspace.activeLeaf.view.containerEl;
      const p = root.querySelectorAll(".tlui-style-panel");
      return { panels: p.length, buttons: [...root.querySelectorAll(".tlui-style-panel button")].map((b) => b.textContent.trim()) };`);
    await client.evaluate(`
      const root = app.workspace.activeLeaf.view.containerEl;
      [...root.querySelectorAll(".tlui-style-panel button")].find((b) => b.textContent.trim() === "supports")?.click(); return true;`);
    await sleep(400);
    const tool = await client.evaluate(`return window.__dgEditor.getCurrentToolId();`);
    const a = await centerOf(ctx, nodes[0].id);
    const b = await centerOf(ctx, nodes[1].id);
    await move(ctx, a.x, a.y, false);
    await mouse(ctx, "mousePressed", a.x, a.y);
    for (let i = 1; i <= 10; i++) await move(ctx, a.x + ((b.x - a.x) * i) / 10, a.y + ((b.y - a.y) * i) / 10);
    await mouse(ctx, "mouseReleased", b.x, b.y);
    await sleep(1200);
    const all = await shapes(ctx);
    const rel = all.find((s) => s.type === "discourse-relation");
    st.nodes = nodes.map((n) => n.id); st.rel = rel?.id; writeState(st);
    const dom = await client.evaluate(`
      const ed = window.__dgEditor; const root = app.workspace.activeLeaf.view.containerEl;
      ${rel ? `ed.select(${json(rel?.id)});` : ""}
      return new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(() => {
        const ind = [...root.querySelectorAll(".tl-shape-indicator, [class*=indicator]")].map((e) => e.tagName + "." + e.getAttribute("class") + " ch=" + e.children.length + " " + (e.getAttribute("data-shape-id") || ""));
        const mask = [...root.querySelectorAll("mask")].map((m) => m.id);
        const defs = !!root.querySelector('[data-testid="ready-pattern-fill-defs"]');
        const html = !!root.querySelector(".tl-html-layer");
        r({ ind: ind.slice(0, 10), mask, defs, html, safari: ed.environment.isSafari, envKeys: Object.keys(ed.environment).slice(0, 15) });
      })));`);
    return { canvas: st.canvas, viewType: st.viewType, panel, tool, nodes: nodes.map((n) => ({ id: n.id, title: n.props.title, w: n.props.w, h: n.props.h, src: n.props.src })), rel, dom };
  },
  expect: (a) => ({ pass: !!a.rel, actual: JSON.stringify(a) }),
};

