      await sleep(300);
      await client.evaluate(`const t = [...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary")); t.focus(); t.select(); return true;`);
      await client.typeText("ev-node with a much much longer title for width");
      await sleep(200);
      await client.evaluate(`[...document.querySelectorAll(".modal-container button")].find((b) => b.textContent.trim() === "Confirm")?.click(); return true;`);
      await sleep(2000);
      const after = (await shapes(ctx)).find((s) => s.id === st.A);
      const fileExists = await client.evaluate(`return !!app.vault.getAbstractFileByPath(${json(st.ev.replace("ev-node.md", "ev-node with a much much longer title for width.md"))});`);
